const items = $input.all();
const results = [];
for (const item of items) {
  const text = (item.json.message?.text || '').trim();
  const chatId = item.json.message?.chat?.id;
  const userId = item.json.message?.from?.id;
  const username = item.json.message?.from?.username || 'user';

  if (text.startsWith('/log')) {
    // Parse: /log lari 5km or /log pushup 30
    const match = text.match(/^\/log\s+(.+?)\s+([\d.]+)\s*(km|m|rep|min|cal)?$/i);
    if (match) {
      results.push({
        json: {
          command: 'log',
          exercise: match[1].trim(),
          value: parseFloat(match[2]),
          unit: (match[3] || 'rep').toLowerCase(),
          userId, username, chatId,
          date: new Date().toISOString().split('T')[0],
          weekNumber: getWeekNumber(new Date()),
          timestamp: new Date().toISOString()
        }
      });
    } else {
      results.push({ json: { command: 'invalid', chatId } });
    }
  } else if (text === '/stats') {
    results.push({ json: { command: 'stats', userId, username, chatId } });
  } else if (text === '/weekly') {
    results.push({ json: { command: 'weekly', userId, username, chatId } });
  } else {
    results.push({ json: { command: 'help', chatId } });
  }
}

function getWeekNumber(d) {
  d = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

return results;

const items = $input.all();
const today = new Date().toISOString().split('T')[0];
const todayWorkouts = items.filter(i => i.json.date === today);
const allExercises = {};
items.forEach(i => {
  const ex = i.json.exercise;
  if (!allExercises[ex]) allExercises[ex] = { total: 0, count: 0, unit: i.json.unit };
  allExercises[ex].total += parseFloat(i.json.value || 0);
  allExercises[ex].count++;
});

let text = `📊 <b>Your Fitness Stats</b>\n\n`;
text += `📅 Today: ${todayWorkouts.length} workouts\n`;
text += `📈 All time: ${items.length} workouts\n\n`;
text += `<b>Exercise Totals:</b>\n`;
Object.entries(allExercises).forEach(([ex, data]) => {
  text += `  🏋️ ${ex}: ${data.total} ${data.unit} (${data.count}x)\n`;
});

return [{ json: { text } }];

const items = $input.all();
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const weekData = items.filter(i => new Date(i.json.timestamp) >= weekAgo);

let text = `📊 <b>Weekly Fitness Summary</b>\n`;
text += `📅 ${weekAgo.toISOString().split('T')[0]} → ${now.toISOString().split('T')[0]}\n\n`;

const byExercise = {};
weekData.forEach(i => {
  const ex = i.json.exercise;
  if (!byExercise[ex]) byExercise[ex] = { total: 0, count: 0, unit: i.json.unit };
  byExercise[ex].total += parseFloat(i.json.value || 0);
  byExercise[ex].count++;
});

if (Object.keys(byExercise).length === 0) {
  text += '⚠️ No workouts recorded this week. Time to get moving!';
} else {
  text += `🏋️ Total sessions: ${weekData.length}\n\n`;
  Object.entries(byExercise).forEach(([ex, data]) => {
    text += `💪 ${ex}: ${data.total} ${data.unit} (${data.count} sessions)\n`;
  });
  text += '\nGreat work! Keep pushing! 🔥';
}

return [{ json: { text } }];
